    row.appendChild(labelWrap);
    row.appendChild(value);

    const fragment = document.createDocumentFragment();
    fragment.appendChild(row);
    if (summaryState?.bonusAccrualBlockedByRedeem) {
      fragment.appendChild(details);
    }
    return fragment;
