  function mountCartPageCheckoutActionInSummary(sectionEl) {
    if (!document.body?.classList.contains("shop-cart-page-active")) return;
    if (!sectionEl || sectionEl.closest(".shop-cart-list") !== openCartSheetCtx?.listEl) return;
    const card = sectionEl.querySelector(".shop-cart-pricing-summary-card");
    const actions = openCartSheetCtx?.cartActionsEl;
    if (!card || !actions) return;
    card.appendChild(actions);

    const floatingHost = document.getElementById("shopCartPageFloatingCheckout");
    const floatingButton = document.getElementById("shopCartPageFloatingCheckoutButton");
    const checkoutButton = actions.querySelector(".shop-checkout-btn");
    const cartPageContent = document.getElementById("shopCartPageContent");
    if (!floatingHost || !floatingButton || !checkoutButton || !cartPageContent) return;

    const syncFloatingCheckout = () => {
      const hasItems = cartItemsResolved().length > 0;
      floatingButton.innerHTML = checkoutButton.innerHTML;
      floatingButton.disabled = checkoutButton.disabled || !hasItems;
      floatingHost.classList.toggle("hidden", !hasItems);
      if (!hasItems) return;

      const inlineRect = checkoutButton.getBoundingClientRect();
      const mobileNav = document.querySelector(".shop-mobile-bottom-container:not(.hidden)");
      const navTop = mobileNav?.getBoundingClientRect().top || window.innerHeight;
      const inlineButtonIsFullyVisible = inlineRect.top >= 0 && inlineRect.bottom <= navTop;
      floatingHost.classList.toggle("is-inline-visible", inlineButtonIsFullyVisible);
    };
    floatingButton._shopCartCheckoutButton = checkoutButton;
    cartPageContent._shopFloatingCheckoutSync = syncFloatingCheckout;

    if (floatingButton.dataset.cartCheckoutBound !== "1") {
      floatingButton.addEventListener("click", () => {
        floatingHost.classList.add("hidden");
        floatingButton._shopCartCheckoutButton?.click();
      });
      floatingButton.dataset.cartCheckoutBound = "1";
    }
    if (cartPageContent.dataset.floatingCheckoutBound !== "1") {
      let frameId = 0;
      cartPageContent.addEventListener("scroll", () => {
        if (frameId) return;
        frameId = requestAnimationFrame(() => {
          frameId = 0;
          cartPageContent._shopFloatingCheckoutSync?.();
        });
      }, { passive: true });
      cartPageContent.dataset.floatingCheckoutBound = "1";
    }
    requestAnimationFrame(syncFloatingCheckout);
  }

  function applyCartPricingLineStatesToList(listEl, lineStates) {
    if (!listEl || !listEl.querySelectorAll) return;
    const statesByKey = new Map(
      (Array.isArray(lineStates) ? lineStates : [])
        .filter((entry) => str(entry?.key || "").trim())
        .map((entry) => [str(entry.key).trim(), entry])
    );
    if (!statesByKey.size) return;

    listEl.querySelectorAll('.shop-cart-item-row[data-cart-key]').forEach((row) => {
      const key = str(row?.getAttribute?.("data-cart-key") || "").trim();
      if (!key) return;
      const stateEntry = statesByKey.get(key);
      if (!stateEntry) return;
      const priceGroup = row.querySelector(".cart-price-group");
      if (!priceGroup) return;
      if (typeof window.setShopCartPriceGroupDomState === "function") {
        window.setShopCartPriceGroupDomState(priceGroup, stateEntry.currentTotal, stateEntry.originalTotal);
        return;
      }
      const currentEl = priceGroup.querySelector(".cart-price");
      const oldEl = priceGroup.querySelector(".cart-old");
      const badgeEl = priceGroup.querySelector(".cart-discount-badge");
      if (currentEl) currentEl.textContent = money(stateEntry.currentTotal);
      if (oldEl) {
        oldEl.textContent = stateEntry.originalTotal > stateEntry.currentTotal
          ? `${moneyNoSign(stateEntry.originalTotal)} \u20BD`
          : "";
        oldEl.classList.toggle("hidden", !(stateEntry.originalTotal > stateEntry.currentTotal));
      }
      if (badgeEl) {
        const showBadge = Number(stateEntry.discountAmount || 0) > 0;
        badgeEl.textContent = showBadge ? `-${moneyNoSign(stateEntry.discountAmount)} \u20BD` : "";
        badgeEl.classList.toggle("hidden", !showBadge);
      }
    });
  }

  function buildCartPricingBonusRedeemDisplayLineStates(lineStates, bonusRedeemAmount) {
    const states = Array.isArray(lineStates)
      ? lineStates.map((entry) => ({ ...entry }))
      : [];
    const totalRedeem = roundPrice(Math.max(0, Number(bonusRedeemAmount || 0)));
    if (!(totalRedeem > 0) || !states.length) return states;

    const eligible = states
      .map((entry, index) => ({
        index,
        currentTotal: roundPrice(Math.max(0, Number(entry?.currentTotal || 0))),
      }))
      .filter((entry) => entry.currentTotal > 0);
    const eligibleTotal = roundPrice(
      eligible.reduce((sum, entry) => sum + Number(entry.currentTotal || 0), 0)
    );
    const appliedTotal = roundPrice(Math.min(totalRedeem, eligibleTotal));
    if (!(appliedTotal > 0)) return states;

    let distributed = 0;
    eligible.forEach((entry, entryIndex) => {
      const remaining = roundPrice(appliedTotal - distributed);
      if (!(remaining > 0)) return;
      const rawShare = entryIndex === eligible.length - 1
        ? remaining
        : roundPrice(appliedTotal * (entry.currentTotal / eligibleTotal));
      const share = roundPrice(Math.min(remaining, entry.currentTotal, rawShare));
      if (!(share > 0)) return;

      const stateEntry = states[entry.index];
      const currentTotal = roundPrice(Math.max(0, entry.currentTotal - share));
      const originalTotal = roundPrice(Math.max(
        Number(stateEntry?.originalTotal || 0),
        Number(entry.currentTotal || 0),
        currentTotal
      ));
      let discountPercent = 0;
      if (originalTotal > currentTotal && originalTotal > 0) {
        discountPercent = Math.round(((originalTotal - currentTotal) / originalTotal) * 100);
      }
      if (!Number.isFinite(discountPercent) || discountPercent <= 0) discountPercent = 0;
      if (discountPercent > 100) discountPercent = 100;

      stateEntry.currentTotal = currentTotal;
      stateEntry.originalTotal = originalTotal > currentTotal ? originalTotal : currentTotal;
      stateEntry.discountPercent = discountPercent;
      if ("discountAmount" in stateEntry) {
        stateEntry.discountAmount = roundPrice(Math.max(0, stateEntry.originalTotal - stateEntry.currentTotal));
      }
      distributed = roundPrice(distributed + share);
    });

    return states;
  }

  function renderCartPricingSummarySection(sectionEl, summaryState) {
    if (!sectionEl || !sectionEl.isConnected) return;
    const content = sectionEl.querySelector(".shop-cart-pricing-summary-content");
    if (!content) return;

    if (!summaryState || summaryState.visible === false) {
      content.innerHTML = "";
      delete content.dataset.ready;
      sectionEl.classList.add("hidden");
      document.getElementById("shopCartPageFloatingCheckout")?.classList.add("hidden");
      return;
    }

    content.innerHTML = "";
    content.dataset.ready = "1";
    sectionEl.classList.remove("hidden");

    const summary = document.createElement("div");
    summary.className = "shop-order-summary";

    if (summaryState.isDelivery) {
      summary.appendChild(createCartPricingSummaryRow("Стоимость доставки", money(summaryState.deliveryCost || 0)));

      if (summaryState.deliveryFreeNote) {
        const freeNote = document.createElement("div");
        freeNote.className = "shop-cart-pricing-summary-note";
        freeNote.textContent = summaryState.deliveryFreeNote;
        summary.appendChild(freeNote);
      }

      if (summaryState.deliveryMinNote) {
        const minNote = document.createElement("div");
        minNote.className = "shop-cart-pricing-summary-note";
        minNote.textContent = summaryState.deliveryMinNote;
        summary.appendChild(minNote);
      }
    }

    if (summaryState.paymentTitle) {
      summary.appendChild(createCartPricingSummaryRow("Оплата", summaryState.paymentTitle));
    }

    if (summaryState.changeFrom != null) {
      summary.appendChild(createCartPricingSummaryRow("Сдача с", money(summaryState.changeFrom)));
    }

    if (summaryState.changeAmount != null) {
      summary.appendChild(createCartPricingSummaryRow("Сдача", money(summaryState.changeAmount)));
    }

    summary.appendChild(createCartPricingSummaryRow("Сумма товаров", money(summaryState.subtotalBeforeDiscount || 0)));

    if (Number(summaryState.discountAmount || 0) > 0) {
      const discountRow = document.createElement("div");
      discountRow.className = "shop-order-summary-row shop-checkout-discount-row";

      const labelWrap = document.createElement("span");
      labelWrap.className = "shop-order-summary-discount-label-wrap";

      const label = document.createElement("span");
      label.className = "shop-order-summary-label";
      label.textContent = "Скидка";
      labelWrap.appendChild(label);

      const detailItems = Array.isArray(summaryState.discountDetailItems)
        ? summaryState.discountDetailItems.filter((entry) => Number(entry?.amount || 0) > 0)
        : [];
      const details = document.createElement("div");
      details.className = "shop-order-summary-discount-breakdown";
      details.setAttribute("aria-hidden", "true");

      detailItems.forEach((entry) => {
        const detailRow = document.createElement("div");
        detailRow.className = "shop-order-summary-discount-breakdown-row";

        const detailLabel = document.createElement("span");
        detailLabel.className = "shop-order-summary-discount-breakdown-label";
        detailLabel.textContent = formatOrderDiscountBreakdownTitle(entry);

        const detailValue = document.createElement("span");
        detailValue.className = "shop-order-summary-discount-breakdown-value";
        detailValue.textContent = `-${money(entry?.amount || 0)}`;

        detailRow.appendChild(detailLabel);
        detailRow.appendChild(detailValue);
        details.appendChild(detailRow);
      });

      if (summaryState.discountDetailNote) {
        const note = document.createElement("div");
        note.className = "shop-order-summary-discount-breakdown-note";
        note.textContent = summaryState.discountDetailNote;
        details.appendChild(note);
      }

      if (detailItems.length > 0 || summaryState.discountDetailNote) {
        const infoBtn = document.createElement("button");
        infoBtn.type = "button";
        infoBtn.className = "shop-order-summary-discount-info-btn";
        infoBtn.setAttribute("aria-label", "Показать расшифровку скидки");
        infoBtn.setAttribute("aria-expanded", "false");
        infoBtn.innerHTML = `<i class="fas fa-info"></i>`;
        infoBtn.addEventListener("click", (event) => {
          event.preventDefault();
          const willOpen = !details.classList.contains("is-open");
          details.classList.toggle("is-open", willOpen);
          details.setAttribute("aria-hidden", willOpen ? "false" : "true");
          infoBtn.setAttribute("aria-expanded", willOpen ? "true" : "false");
        });
        labelWrap.appendChild(infoBtn);
      }

      const discountValue = document.createElement("span");
      discountValue.className = "shop-order-summary-value shop-checkout-discount-value";
      discountValue.textContent = `-${money(summaryState.discountAmount || 0)}`;

      discountRow.appendChild(labelWrap);
      discountRow.appendChild(discountValue);
      summary.appendChild(discountRow);

      if (detailItems.length > 0 || summaryState.discountDetailNote) {
        summary.appendChild(details);
      }
    }

    if (Number(summaryState.bonusAccrualAmount || 0) > 0) {
      summary.appendChild(createCartBonusAccrualSummaryRow(summaryState));
    }

    const divider = document.createElement("div");
    divider.className = "shop-order-summary-divider";
    summary.appendChild(divider);

    const totalRow = document.createElement("div");
    totalRow.className = "shop-order-summary-total-row";

    const totalLabel = document.createElement("span");
    totalLabel.className = "shop-order-summary-total-label";
    totalLabel.textContent = "Итого";

    const totalValue = document.createElement("span");
    totalValue.className = "shop-order-summary-total-value";
    totalValue.textContent = money(summaryState.total || 0);

    totalRow.appendChild(totalLabel);
    totalRow.appendChild(totalValue);
    summary.appendChild(totalRow);

    content.appendChild(summary);
    mountCartPageCheckoutActionInSummary(sectionEl);
  }

  async function buildCartPricingSummaryState() {
    const cartItems = cartItemsResolved();
    if (!Array.isArray(cartItems) || !cartItems.length) {
      return {
        visible: false,
        lineStates: [],
      };
    }

    const cartTotals = computeCartTotals(cartItems);
    const draft = loadCheckoutDraft();
    let config = null;
    try {
      config = await getOrderConfig();
    } catch (_) {}

    const methodCode = resolveCartPricingMethodCode(config, draft);
    const paymentState = resolveCartPricingPaymentState(config, draft);

    const previewRequest = buildCheckoutBenefitsPreviewRequest({
      items: cartItems,
      methodCode,
      promoCode: draft?.promo_code || "",
      selectedDiscountId: draft?.selected_discount_id,
      selectedDiscountSource: draft?.selected_discount_source,
      selectedPromoSource: draft?.selected_promo_source,
      selectedPromoRewardId: draft?.selected_promo_reward_id,
    });

    let previewData = null;
    try {
      const nextPreviewData = await fetchCheckoutBenefitsPreview(previewRequest);
      if (nextPreviewData) {
        previewData = nextPreviewData;
      }
    } catch (_) {}

    const localPreviewData = buildLocalCheckoutBenefitsPreviewData(previewData, {
      previewRequest,
      selectedDiscountId: draft?.selected_discount_id,
      selectedDiscountSource: draft?.selected_discount_source,
      promoCode: draft?.promo_code || "",
      selectedPromoSource: draft?.selected_promo_source,
      selectedPromoRewardId: draft?.selected_promo_reward_id,
    });

    const previewSummary = localPreviewData?.summary
      || (previewData?.summary ? cloneCheckoutBenefitsSummary(previewData.summary) : null);
    const totalsForPricing = {
      nonAutoTotal: Number(cartTotals.nonAutoTotal || 0),
      autoEligibleTotal: Number(cartTotals.autoEligibleTotal || 0),
    };
    const giftRewardDiscount = calculateCartGiftRewardDisplayDiscount(cartItems, totalsForPricing);
    const subtotalBeforeDiscountRaw = previewSummary
      ? roundPrice(Number(previewSummary.subtotal || 0))
      : roundPrice(Number(cartTotals.totalBeforeDiscount || cartTotals.total || 0));
    const itemsTotal = previewSummary
      ? roundPrice(Number(previewSummary.items_total || 0))
      : roundPrice(Number(cartTotals.total || 0));
    const discountAmountRaw = previewSummary
      ? roundPrice(Number(previewSummary.discount_total || 0))
      : roundPrice(Math.max(0, subtotalBeforeDiscountRaw - itemsTotal));
    const subtotalBeforeDiscount = roundPrice(
      Math.max(0, Number(subtotalBeforeDiscountRaw || 0) - Number(giftRewardDiscount || 0))
    );
    let discountAmount = roundPrice(
      Math.max(0, Number(discountAmountRaw || 0) - Number(giftRewardDiscount || 0))
    );
    const orderLevelDiscount = roundPrice(Math.max(0, Number(cartTotals.total || 0) - itemsTotal));

    const selectedBenefitTitles = getCartPricingSelectedBenefitTitles(localPreviewData || previewData);
    const discountDetails = buildCartPricingDiscountDetails({
      previewSummary,
      cartItems,
      totalsForPricing,
      actualDiscount: discountAmountRaw,
      orderLevelDiscount,
      giftRewardDiscount,
      selectedBenefitTitles,
    });

    let deliveryQuote = null;
    let defaultDeliverySettings = null;
    if (str(methodCode || "").trim() === "delivery") {
      try {
        deliveryQuote = await getDeliveryQuote(itemsTotal);
      } catch (_) {
        try {
          defaultDeliverySettings = await getDeliverySettings();
        } catch (_) {}
      }

      if (
        !defaultDeliverySettings &&
        (
          deliveryQuote?.eta_minutes == null ||
          deliveryQuote?.free_delivery_from == null ||
          !Array.isArray(deliveryQuote?.price_tiers) ||
          !deliveryQuote.price_tiers.length
        )
      ) {
        try {
          defaultDeliverySettings = await getDeliverySettings();
        } catch (_) {}
      }
    }

    const deliveryState = resolveCartPricingDeliveryState(
      itemsTotal,
      methodCode,
      deliveryQuote,
      defaultDeliverySettings
    );
    const total = roundPrice(itemsTotal + (deliveryState.isDelivery ? Number(deliveryState.cost || 0) : 0));
    const changeState = resolveCartPricingChangeState(draft, total, paymentState.code);

    return {
      visible: true,
      isDelivery: deliveryState.isDelivery,
      deliveryCost: Number(deliveryState.cost || 0),
      deliveryFreeNote: deliveryState.freeNote,
      deliveryMinNote: deliveryState.minNote,
      paymentTitle: paymentState.title,
      changeFrom: changeState.changeFrom,
      changeAmount: changeState.changeAmount,
      subtotalBeforeDiscount,
      discountAmount,
      discountDetailItems: discountDetails.items,
      discountDetailNote: discountDetails.note,
      total,
      lineStates: buildCartPricingLineStates(cartItems, itemsTotal),
    };
  }

  let cartPricingSummarySyncSeq = 0;

  async function syncCartPricingSummaryUi() {
    const sections = Array.from(document.querySelectorAll(".shop-cart-pricing-summary-section"))
      .filter((node) => node && node.isConnected);
    if (!sections.length) return;

    const seq = ++cartPricingSummarySyncSeq;
    sections.forEach((section) => setCartPricingSummaryLoading(section));

    let summaryState = null;
    try {
      summaryState = await buildCartPricingSummaryState();
    } catch (error) {
      console.warn("Failed to sync cart pricing summary:", error);
      summaryState = {
        visible: false,
        lineStates: [],
      };
    }
    if (seq !== cartPricingSummarySyncSeq) return;

    sections.forEach((section) => {
      renderCartPricingSummarySection(section, summaryState);
      const listEl = section.parentElement;
      if (listEl && summaryState && Array.isArray(summaryState.lineStates)) {
        applyCartPricingLineStatesToList(listEl, summaryState.lineStates);
      }
    });
  }

  window.syncShopCartPricingSummaryUi = syncCartPricingSummaryUi;

  const CART_PRICING_PAYMENT_TITLE_FALLBACKS = {
    cash: "Наличные",
    card: "Картой",
    online: "Онлайн",
    sbp: "СБП / QR",
    qr: "Картой / QR",
    card_qr: "Картой / QR",
    cashless: "Картой",
  };

  function getCartPricingCachedPreviewBundle(cartItems, methodCode, draft) {
    const previewRequest = buildCheckoutBenefitsPreviewRequest({
      items: cartItems,
      methodCode,
      promoCode: draft?.promo_code || "",
      selectedDiscountId: draft?.selected_discount_id,
      selectedDiscountSource: draft?.selected_discount_source,
      selectedPromoSource: draft?.selected_promo_source,
      selectedPromoRewardId: draft?.selected_promo_reward_id,
    });
    const storeSnapshot = getBenefitsStoreSnapshot(previewRequest);
    const exactPreviewData = peekWarmCheckoutBenefitsPreviewCache(previewRequest);
    const scopePreviewData = peekWarmCheckoutBenefitsScopePreviewCache(previewRequest);
    const fallbackStoreBasePreview = checkoutBenefitsStore?.basePreview && typeof checkoutBenefitsStore.basePreview === "object"
      ? checkoutBenefitsStore.basePreview
      : null;
    const calculationFallbackPreview = hasCheckoutBenefitsLocalCalculationPayload(checkoutBenefitsStore?.calculationPreview)
      ? checkoutBenefitsStore.calculationPreview
      : null;
    const deriveSourcePreview = storeSnapshot?.basePreview
      || scopePreviewData
      || fallbackStoreBasePreview
      || calculationFallbackPreview
      || null;
    const localDeriveSourcePreview = hasCheckoutBenefitsLocalCalculationPayload(deriveSourcePreview)
      ? deriveSourcePreview
      : (calculationFallbackPreview || deriveSourcePreview);
    const localPreviewData = exactPreviewData
      || storeSnapshot?.derivedPreview
      || (localDeriveSourcePreview
        ? buildLocalCheckoutBenefitsPreviewData(localDeriveSourcePreview, {
            previewRequest,
            selectedDiscountId: draft?.selected_discount_id,
            selectedDiscountSource: draft?.selected_discount_source,
            promoCode: draft?.promo_code || "",
            selectedPromoSource: draft?.selected_promo_source,
            selectedPromoRewardId: draft?.selected_promo_reward_id,
          })
        : null);
    if (!localPreviewData && !exactPreviewData) {
      const appliedSnapshot = getCheckoutBenefitsAppliedSnapshotFromDraft(draft, previewRequest);
      const snapshotPreviewData = buildCheckoutBenefitsPreviewDataFromAppliedSnapshot(appliedSnapshot);
      return {
        previewData: snapshotPreviewData,
        localPreviewData: snapshotPreviewData,
        previewSummary: snapshotPreviewData?.summary
          ? cloneCheckoutBenefitsSummary(snapshotPreviewData.summary)
          : null,
      };
    }
    return {
      previewData: exactPreviewData || null,
      localPreviewData,
      previewSummary: localPreviewData?.summary
        || (exactPreviewData?.summary ? cloneCheckoutBenefitsSummary(exactPreviewData.summary) : null),
    };
  }

  function getCartPricingCachedDeliveryQuote(subtotal = null) {
    const cacheMeta = buildCurrentDeliveryQuoteCacheMeta(subtotal);
    const exactQuote = readCachedDeliveryQuoteFromMemory(cacheMeta);
    if (exactQuote) return exactQuote;

    const persistentQuote = buildPersistentCachedDeliveryQuote(cacheMeta);
    if (!persistentQuote) return null;

    return storeDeliveryQuoteInMemory(cacheMeta, persistentQuote);
  }

  function getCartPricingCachedDeliverySettings() {
    return getCachedDeliverySettingsForCurrentScope();
  }

  function calculateCartGiftRewardDisplayDiscount(cartItems, totalsForPricing) {
    const safeItems = Array.isArray(cartItems) ? cartItems : [];
    const pricingTotals = {
      nonAutoTotal: Number(totalsForPricing?.nonAutoTotal || 0),
      autoEligibleTotal: Number(totalsForPricing?.autoEligibleTotal || 0),
    };
    let giftRewardDiscount = 0;

    safeItems.forEach((item) => {
      const qty = Math.max(0, Number(item?.qty || 0));
      if (!qty) return;
      if (Number(item?.is_gift_reward || 0) !== 1) return;
      if (item?.type === "combo") return;

      const pricing = computeItemPricing(item, pricingTotals);
      const parts = pricing.parts || {};
      const product = item?.product || {};

      let originalUnit = roundPrice(Number(pricing.unitPrice || 0));
      if (Number(product?.original_price || 0) > 0) {
        originalUnit = roundPrice(
          Number(product.original_price || 0)
          + Number(parts.optionTotal || 0)
          + Number(parts.ingredientDiff || 0)
        );
      } else {
        const scaledOldBase = scaleProductBasePriceForCurrentUnit(
          product,
          Number(parts.baseProductUnit || pricing.unitPrice || 0),
          Number(product?.old_price || 0)
        );
        if (scaledOldBase > Number(pricing.unitPrice || 0)) {
          originalUnit = roundPrice(
            scaledOldBase
            + Number(parts.optionTotal || 0)
            + Number(parts.ingredientDiff || 0)
          );
        } else if (Number(item?.unit_price_before_discount || 0) > Number(pricing.unitPrice || 0)) {
          originalUnit = roundPrice(Number(item.unit_price_before_discount || 0));
        }
      }

      const originalQty = Number.isFinite(Number(pricing.paidQty))
        ? Math.max(0, Number(pricing.paidQty))
        : qty;
      const originalLineTotal = roundPrice(originalUnit * originalQty);
      const lineTotal = roundPrice(Number(pricing.lineTotal || 0));
      giftRewardDiscount += roundPrice(Math.max(0, originalLineTotal - lineTotal));
    });

    return roundPrice(giftRewardDiscount);
  }

  function buildCartPricingDiscountBreakdown(cartItems, totalsForPricing, summaryDiscount, orderLevelDiscount) {
    const safeItems = Array.isArray(cartItems) ? cartItems : [];
    const pricingTotals = {
      nonAutoTotal: Number(totalsForPricing?.nonAutoTotal || 0),
      autoEligibleTotal: Number(totalsForPricing?.autoEligibleTotal || 0),
    };
    let comboDiscount = 0;
    let productDiscount = 0;
    let autoAddDiscount = 0;
    const customerOrderDiscount = roundPrice(Math.max(0, Number(orderLevelDiscount) || 0));

    safeItems.forEach((item) => {
      const qty = Math.max(0, Number(item?.qty || 0));
      if (!qty) return;
      if (Number(item?.is_gift_reward || 0) === 1) return;

      if (item.type === "combo") {
        const currentUnit = roundPrice(Number(item.unit_price_override || 0));
        const oldRaw = Number(item.unit_price_before_discount || 0);
        const oldUnit = oldRaw > currentUnit ? roundPrice(oldRaw) : currentUnit;
        comboDiscount += roundPrice(Math.max(0, (oldUnit - currentUnit) * qty));
        return;
      }

      const pricing = computeItemPricing(item, pricingTotals);
      const parts = pricing.parts || {};
      const product = item?.product || {};

      let originalUnit = roundPrice(Number(pricing.unitPrice || 0));
      if (Number(product?.original_price || 0) > 0) {
        originalUnit = roundPrice(
          Number(product.original_price || 0)
          + Number(parts.optionTotal || 0)
          + Number(parts.ingredientDiff || 0)
        );
      } else {
        const scaledOldBase = scaleProductBasePriceForCurrentUnit(
          product,
          Number(parts.baseProductUnit || pricing.unitPrice || 0),
          Number(product?.old_price || 0)
        );
        if (scaledOldBase > Number(pricing.unitPrice || 0)) {
          originalUnit = roundPrice(
            scaledOldBase
            + Number(parts.optionTotal || 0)
            + Number(parts.ingredientDiff || 0)
          );
        }
      }

      const originalQty = Number.isFinite(Number(pricing.paidQty))
        ? Math.max(0, Number(pricing.paidQty))
        : qty;
      const originalLineTotal = roundPrice(originalUnit * originalQty);
      const lineTotal = roundPrice(Number(pricing.lineTotal || 0));
      const lineDiscount = roundPrice(Math.max(0, originalLineTotal - lineTotal));
      if (!(lineDiscount > 0)) return;

      if (pricing.isAuto || Number(item?.auto_add || 0) === 1) {
        autoAddDiscount += lineDiscount;
      } else {
        productDiscount += lineDiscount;
      }
    });

    comboDiscount = roundPrice(comboDiscount);
    productDiscount = roundPrice(productDiscount);
    autoAddDiscount = roundPrice(autoAddDiscount);

    const totalKnown = roundPrice(comboDiscount + productDiscount + autoAddDiscount + customerOrderDiscount);
    const target = roundPrice(Number(summaryDiscount) || 0);
    const otherDiscount = roundPrice(Math.max(0, target - totalKnown));

    return {
      comboDiscount,
      productDiscount,
      autoAddDiscount,
      customerOrderDiscount,
      otherDiscount,
    };
  }

  function buildCartPricingDiscountDetails({
    previewSummary = null,
    cartItems = [],
    totalsForPricing = null,
    actualDiscount = 0,
    orderLevelDiscount = 0,
    giftRewardDiscount = 0,
    selectedBenefitTitles = [],
  } = {}) {
    const previewRowsRaw = Array.isArray(previewSummary?.discount_breakdown)
      ? previewSummary.discount_breakdown
          .map((entry, index) => ({
            key: str(entry?.key || entry?.title || `discount_${index}`),
            title: str(entry?.title || "Скидка"),
            amount: roundPrice(Number(entry?.amount || 0)),
            promoCode: str(entry?.promoCode || entry?.promo_code || "").trim().toUpperCase() || null,
            promo_code: str(entry?.promoCode || entry?.promo_code || "").trim().toUpperCase() || null,
          }))
          .filter((entry) => entry.amount > 0)
      : [];
    let resolvedGiftRewardDiscount = roundPrice(Math.max(0, Number(giftRewardDiscount || 0)));
    if (!(resolvedGiftRewardDiscount > 0)) {
      resolvedGiftRewardDiscount = calculateCartGiftRewardDisplayDiscount(cartItems, totalsForPricing);
    }
    const previewRows = normalizeCartPricingPreviewDiscountRows(previewRowsRaw, resolvedGiftRewardDiscount);
    const effectiveActualDiscount = roundPrice(
      Math.max(0, Number(actualDiscount || 0) - Number(resolvedGiftRewardDiscount || 0))
    );

    if (previewRows.length) {
      return {
        items: previewRows,
        note: "",
      };
    }

    const breakdown = buildCartPricingDiscountBreakdown(
      cartItems,
      totalsForPricing,
      effectiveActualDiscount,
      orderLevelDiscount
    );

    const items = [
      { key: "combo", title: "Комбо", amount: Number(breakdown.comboDiscount || 0) },
      { key: "product", title: "Товарные скидки", amount: Number(breakdown.productDiscount || 0) },
      { key: "auto_add", title: "Автодобавление", amount: Number(breakdown.autoAddDiscount || 0) },
      { key: "customer", title: "Клиентская скидка", amount: Number(breakdown.customerOrderDiscount || 0) },
      { key: "other", title: "Прочие скидки", amount: Number(breakdown.otherDiscount || 0) },
    ].filter((entry) => entry.amount > 0);

    const note = selectedBenefitTitles.length && Number(orderLevelDiscount || 0) > 0
      ? `Скидка клиента: ${selectedBenefitTitles.join(", ")}`
      : "";

    return { items, note };
  }

  function resolveCartPricingMethodCode(draft) {
    const draftCode = str(
      draft?.method_code
      || window._checkoutMethodCode
      || ""
    ).trim();
    if (draftCode) return draftCode;
    return window._deliveryMode === "pickup" ? "takeaway" : "delivery";
  }

  function resolveCartPricingPaymentState(draft) {
    const draftCode = str(draft?.payment_code || "").trim();
    if (!draftCode) {
      return { code: "", title: "" };
    }
    const configPayments = Array.isArray(orderConfigCache?.payments)
      ? orderConfigCache.payments
      : (Array.isArray(window.__shopOrderConfig?.payments) ? window.__shopOrderConfig.payments : []);
    const payment = configPayments.find((entry) => str(entry?.code || "").trim() === draftCode) || null;
    return {
      code: draftCode,
      title: str(payment?.title || CART_PRICING_PAYMENT_TITLE_FALLBACKS[draftCode] || "").trim(),
    };
  }

  function resolveCartPricingChangeState(draft, payableTotal, paymentCode) {
    const normalizedPaymentCode = str(paymentCode || "").trim();
    const changeFrom = roundPrice(Number(draft?.change_from || 0));
    if (normalizedPaymentCode !== "cash" || !(changeFrom > payableTotal)) {
      return {
        changeFrom: null,
        changeAmount: null,
      };
    }
    return {
      changeFrom,
      changeAmount: roundPrice(changeFrom - payableTotal),
    };
  }

  function resolveCartPricingDeliveryState(orderTotal, methodCode, deliveryQuote, defaultDeliverySettings = null) {
    const isDelivery = str(methodCode || "").trim() === "delivery";
    if (!isDelivery) {
      return {
        isDelivery: false,
        cost: 0,
        freeFrom: null,
        minOrder: 0,
        freeNote: "",
        minNote: "",
      };
    }

    const tierSummary = resolveDeliveryTierSummaryForTotal(orderTotal, deliveryQuote, defaultDeliverySettings);
    const freeFromRaw = tierSummary?.free_delivery_from != null
      ? Number(tierSummary.free_delivery_from)
      : (deliveryQuote?.free_delivery_from != null
        ? Number(deliveryQuote.free_delivery_from)
        : (defaultDeliverySettings?.free_delivery_from != null ? Number(defaultDeliverySettings.free_delivery_from) : null));
    const minOrderRaw = tierSummary?.min_order_amount != null
      ? Number(tierSummary.min_order_amount)
      : (deliveryQuote?.min_order_amount != null
        ? Number(deliveryQuote.min_order_amount)
        : Number(defaultDeliverySettings?.min_order_amount || 0));
    const baseCostRaw = tierSummary?.delivery_cost != null
      ? Number(tierSummary.delivery_cost)
      : (deliveryQuote?.delivery_cost != null
        ? Number(deliveryQuote.delivery_cost)
        : Number(defaultDeliverySettings?.delivery_cost || 0));

    let cost = Number.isFinite(baseCostRaw) && baseCostRaw > 0 ? baseCostRaw : 0;
    if (Number.isFinite(freeFromRaw) && orderTotal >= freeFromRaw) {
      cost = 0;
    }

    let freeNote = "";
    if (Number.isFinite(freeFromRaw)) {
      freeNote = freeFromRaw <= 0
        ? "Доставка бесплатно"
        : `Бесплатно от ${money(freeFromRaw)}`;
    }

    let minNote = "";
    if (Number.isFinite(minOrderRaw) && minOrderRaw > 0) {
      if (orderTotal < minOrderRaw) {
        minNote = `Минимальная сумма заказа ${money(minOrderRaw)}. Добавьте ещё ${money(minOrderRaw - orderTotal)}.`;
      } else {
        minNote = `Минимальная сумма заказа ${money(minOrderRaw)}.`;
      }
    }

    return {
      isDelivery: true,
      cost: roundPrice(cost),
      freeFrom: Number.isFinite(freeFromRaw) ? roundPrice(freeFromRaw) : null,
      minOrder: Number.isFinite(minOrderRaw) ? roundPrice(minOrderRaw) : 0,
      freeNote,
      minNote,
    };
  }

  function buildCartPricingLineStates(cartItems, finalItemsTotal, previewData = null) {
    const safeItems = Array.isArray(cartItems) ? cartItems : [];
    const cartTotals = computeCartTotals(safeItems);
    const pricingTotals = {
      nonAutoTotal: Number(cartTotals?.nonAutoTotal || 0),
      autoEligibleTotal: Number(cartTotals?.autoEligibleTotal || 0),
    };
    const localLineTotalsByCartKey = previewData?.local_line_totals_by_cart_key && typeof previewData.local_line_totals_by_cart_key === "object"
      ? previewData.local_line_totals_by_cart_key
      : null;
    const lineStates = [];

    safeItems.forEach((item) => {
      const qty = Math.max(0, Number(item?.qty || 0));
      const key = str(item?.key || "").trim();
      if (!qty || !key) return;

      if (str(item?.type || "").trim() === "combo") {
        const currentUnit = roundPrice(Number(item?.unit_price_override || 0));
        const oldRaw = Number(item?.unit_price_before_discount || 0);
        const oldUnit = oldRaw > currentUnit ? roundPrice(oldRaw) : currentUnit;
        const localLineTotal = localLineTotalsByCartKey
          ? Number(localLineTotalsByCartKey[key])
          : NaN;
        lineStates.push({
          key,
          baseTotal: Number.isFinite(localLineTotal)
            ? roundPrice(Math.max(0, localLineTotal))
            : roundPrice(currentUnit * qty),
          originalTotal: roundPrice(Math.max(oldUnit * qty, currentUnit * qty)),
        });
        return;
      }

      const pricing = computeItemPricing(item, pricingTotals);
      const parts = pricing.parts || {};
      const product = item?.product || {};
      const paidQty = Number.isFinite(Number(pricing?.paidQty))
        ? Math.max(0, Number(pricing.paidQty))
        : qty;
      const storedOriginalLineTotal = Number(item?.discount?.original_line_total || 0);
      const storedOriginalUnitPrice = Number(item?.unit_price_before_discount || 0);

      let originalUnit = roundPrice(Number(pricing?.unitPrice || 0));
      if (storedOriginalUnitPrice > 0) {
        originalUnit = roundPrice(storedOriginalUnitPrice);
      } else if (storedOriginalLineTotal > 0 && paidQty > 0) {
        originalUnit = roundPrice(storedOriginalLineTotal / paidQty);
      } else if (Number(product?.original_price || 0) > 0) {
        originalUnit = roundPrice(
          Number(product.original_price || 0)
          + Number(parts.optionTotal || 0)
          + Number(parts.ingredientDiff || 0)
        );
      } else {
        const scaledOldBase = scaleProductBasePriceForCurrentUnit(
          product,
          Number(parts.baseProductUnit || pricing?.unitPrice || 0),
          Number(product?.old_price || 0)
        );
        if (scaledOldBase > Number(pricing?.unitPrice || 0)) {
          originalUnit = roundPrice(
            scaledOldBase
            + Number(parts.optionTotal || 0)
            + Number(parts.ingredientDiff || 0)
          );
        }
      }

      const localLineTotal = localLineTotalsByCartKey
        ? Number(localLineTotalsByCartKey[key])
        : NaN;
      const baseTotal = Number.isFinite(localLineTotal)
        ? roundPrice(Math.max(0, localLineTotal))
        : roundPrice(Number(pricing?.lineTotal || 0));
      const originalTotal = roundPrice(Math.max(
        storedOriginalLineTotal > 0 ? storedOriginalLineTotal : 0,
        originalUnit * paidQty,
        baseTotal
      ));
      lineStates.push({
        key,
        baseTotal,
        originalTotal,
      });
    });

    const baseLinesTotal = roundPrice(
      lineStates.reduce((sum, entry) => sum + Number(entry?.baseTotal || 0), 0)
    );
    const extraOrderDiscount = roundPrice(Math.max(
      0,
      baseLinesTotal - roundPrice(Number(finalItemsTotal || 0))
    ));
    const distributedByIndex = distributeCartPricingDiscountAcrossLines(lineStates, extraOrderDiscount);

    return lineStates.map((entry, index) => {
      const allocatedDiscount = roundPrice(Number(distributedByIndex.get(index) || 0));
      const currentTotal = roundPrice(Math.max(0, entry.baseTotal - allocatedDiscount));
      const originalTotal = roundPrice(Math.max(entry.originalTotal, entry.baseTotal, currentTotal));
      let discountPercent = 0;
      if (originalTotal > currentTotal && originalTotal > 0) {
        discountPercent = Math.round(((originalTotal - currentTotal) / originalTotal) * 100);
      }
      if (!Number.isFinite(discountPercent) || discountPercent <= 0) discountPercent = 0;
      if (discountPercent > 100) discountPercent = 100;
      return {
        key: entry.key,
        currentTotal,
        originalTotal: originalTotal > currentTotal ? originalTotal : currentTotal,
        discountPercent,
      };
    });
  }

  function setCartPricingSummaryLoading(sectionEl) {
    if (!sectionEl || !sectionEl.isConnected) return;
    const content = sectionEl.querySelector(".shop-cart-pricing-summary-content");
    if (!content || content.dataset.ready === "1") return;
    content.innerHTML = '<div class="shop-cart-pricing-summary-loading">Пересчитываем суммы...</div>';
    sectionEl.classList.remove("hidden");
  }

  function applyCartPricingLineStatesToList(listEl, lineStates) {
    if (!listEl || !listEl.querySelectorAll) return;
    const statesByKey = new Map(
      (Array.isArray(lineStates) ? lineStates : [])
        .filter((entry) => str(entry?.key || "").trim())
        .map((entry) => [str(entry.key).trim(), entry])
    );
    if (!statesByKey.size) return;

    listEl.querySelectorAll('.shop-cart-item-row[data-cart-key]').forEach((row) => {
      const key = str(row?.getAttribute?.("data-cart-key") || "").trim();
      if (!key) return;
      const stateEntry = statesByKey.get(key);
      if (!stateEntry) return;
      const priceGroup = row.querySelector(".cart-price-group");
      if (!priceGroup) return;
      if (typeof window.setShopCartPriceGroupDomState === "function") {
        window.setShopCartPriceGroupDomState(priceGroup, stateEntry);
        return;
      }
      const currentEl = priceGroup.querySelector(".cart-price");
      const oldEl = priceGroup.querySelector(".cart-old");
      const badgeEl = priceGroup.querySelector(".cart-discount-badge");
      if (currentEl) currentEl.textContent = money(stateEntry.currentTotal);
      if (oldEl) {
        oldEl.textContent = stateEntry.originalTotal > stateEntry.currentTotal
          ? money(stateEntry.originalTotal)
          : "";
        oldEl.classList.toggle("hidden", !(stateEntry.originalTotal > stateEntry.currentTotal));
      }
      if (badgeEl) {
        const showBadge = Number(stateEntry.discountPercent || 0) > 0;
        badgeEl.textContent = showBadge ? `-${stateEntry.discountPercent}%` : "";
        badgeEl.classList.toggle("hidden", !showBadge);
      }
    });
  }

  function renderCartPricingSummarySection(sectionEl, summaryState) {
    if (!sectionEl || !sectionEl.isConnected) return;
    const content = sectionEl.querySelector(".shop-cart-pricing-summary-content");
    if (!content) return;

    if (!summaryState || summaryState.visible === false) {
      content.innerHTML = "";
      delete content.dataset.ready;
      sectionEl.classList.add("hidden");
      document.getElementById("shopCartPageFloatingCheckout")?.classList.add("hidden");
      return;
    }

    content.innerHTML = "";
    content.dataset.ready = "1";
    sectionEl.classList.remove("hidden");

    const summary = document.createElement("div");
    summary.className = "shop-order-summary";

    if (summaryState.isDelivery) {
      summary.appendChild(createCartPricingSummaryRow("Стоимость доставки", money(summaryState.deliveryCost || 0)));

      if (summaryState.deliveryFreeNote) {
        const freeNote = document.createElement("div");
        freeNote.className = "shop-cart-pricing-summary-note";
        freeNote.textContent = summaryState.deliveryFreeNote;
        summary.appendChild(freeNote);
      }

      if (summaryState.deliveryMinNote) {
        const minNote = document.createElement("div");
        minNote.className = "shop-cart-pricing-summary-note";
        minNote.textContent = summaryState.deliveryMinNote;
        summary.appendChild(minNote);
      }
    }

    if (summaryState.paymentTitle) {
      summary.appendChild(createCartPricingSummaryRow("Оплата", summaryState.paymentTitle));
    }

    if (summaryState.changeFrom != null) {
      summary.appendChild(createCartPricingSummaryRow("Сдача с", money(summaryState.changeFrom)));
    }

    if (summaryState.changeAmount != null) {
      summary.appendChild(createCartPricingSummaryRow("Сдача", money(summaryState.changeAmount)));
    }

    summary.appendChild(createCartPricingSummaryRow("Сумма товаров", money(summaryState.subtotalBeforeDiscount || 0)));

    if (Number(summaryState.discountAmount || 0) > 0) {
      const discountRow = document.createElement("div");
      discountRow.className = "shop-order-summary-row shop-checkout-discount-row";

      const labelWrap = document.createElement("span");
      labelWrap.className = "shop-order-summary-discount-label-wrap";

      const label = document.createElement("span");
      label.className = "shop-order-summary-label";
      label.textContent = "Скидка";
      labelWrap.appendChild(label);

      const detailItems = Array.isArray(summaryState.discountDetailItems)
        ? summaryState.discountDetailItems.filter((entry) => Number(entry?.amount || 0) > 0)
        : [];
      const details = document.createElement("div");
      details.className = "shop-order-summary-discount-breakdown";
      details.setAttribute("aria-hidden", "true");

      detailItems.forEach((entry) => {
        const detailRow = document.createElement("div");
        detailRow.className = "shop-order-summary-discount-breakdown-row";

        const detailLabel = document.createElement("span");
        detailLabel.className = "shop-order-summary-discount-breakdown-label";
        detailLabel.textContent = formatOrderDiscountBreakdownTitle(entry);

        const detailValue = document.createElement("span");
        detailValue.className = "shop-order-summary-discount-breakdown-value";
        detailValue.textContent = `-${money(entry?.amount || 0)}`;

        detailRow.appendChild(detailLabel);
        detailRow.appendChild(detailValue);
        details.appendChild(detailRow);
      });

      if (summaryState.discountDetailNote) {
        const note = document.createElement("div");
        note.className = "shop-order-summary-discount-breakdown-note";
        note.textContent = summaryState.discountDetailNote;
        details.appendChild(note);
      }

      if (detailItems.length > 0 || summaryState.discountDetailNote) {
        const infoBtn = document.createElement("button");
        infoBtn.type = "button";
        infoBtn.className = "shop-order-summary-discount-info-btn";
        infoBtn.setAttribute("aria-label", "Показать расшифровку скидки");
        infoBtn.setAttribute("aria-expanded", "false");
        infoBtn.innerHTML = `<i class="fas fa-info"></i>`;
        infoBtn.addEventListener("click", (event) => {
          event.preventDefault();
          const willOpen = !details.classList.contains("is-open");
          details.classList.toggle("is-open", willOpen);
          details.setAttribute("aria-hidden", willOpen ? "false" : "true");
          infoBtn.setAttribute("aria-expanded", willOpen ? "true" : "false");
        });
        labelWrap.appendChild(infoBtn);
      }

      const discountValue = document.createElement("span");
      discountValue.className = "shop-order-summary-value shop-checkout-discount-value";
      discountValue.textContent = `-${money(summaryState.discountAmount || 0)}`;

      discountRow.appendChild(labelWrap);
      discountRow.appendChild(discountValue);
      summary.appendChild(discountRow);

      if (detailItems.length > 0 || summaryState.discountDetailNote) {
        summary.appendChild(details);
      }
    }

    if (Number(summaryState.bonusAccrualAmount || 0) > 0) {
      summary.appendChild(createCartBonusAccrualSummaryRow(summaryState));
    }

    const divider = document.createElement("div");
    divider.className = "shop-order-summary-divider";
    summary.appendChild(divider);

    const totalRow = document.createElement("div");
    totalRow.className = "shop-order-summary-total-row";

    const totalLabel = document.createElement("span");
    totalLabel.className = "shop-order-summary-total-label";
    totalLabel.textContent = "Итого";

    const totalValue = document.createElement("span");
    totalValue.className = "shop-order-summary-total-value";
    totalValue.textContent = money(summaryState.total || 0);

    totalRow.appendChild(totalLabel);
    totalRow.appendChild(totalValue);
    summary.appendChild(totalRow);

    content.appendChild(summary);
    mountCartPageCheckoutActionInSummary(sectionEl);
  }

  let cartPricingSnapshotCacheKey = "";
  let cartPricingSnapshotCacheValue = null;

  function invalidateCartPricingSnapshotCache() {
    cartPricingSnapshotCacheKey = "";
    cartPricingSnapshotCacheValue = null;
  }

  function buildCartPricingSnapshotUncached() {
    const cartItems = cartItemsResolved();
    if (!Array.isArray(cartItems) || !cartItems.length) {
      return {
        visible: false,
        lineStates: [],
      };
    }

    const cartTotals = computeCartTotals(cartItems);
    const draft = loadCheckoutDraft();
    const methodCode = resolveCartPricingMethodCode(draft);
    const previewBundle = getCartPricingCachedPreviewBundle(cartItems, methodCode, draft);
    const hasSelectedOrderBenefit = Boolean(
      normalizeCheckoutSelectedDiscountId(draft?.selected_discount_id)
      || normalizeCheckoutBenefitsPromoInputValue(draft?.promo_code || "", { trim: true })
      || normalizeCheckoutSelectedDiscountId(draft?.selected_promo_reward_id)
    );
    const canApplyPreviewSummary = hasSelectedOrderBenefit && !!previewBundle.previewSummary;
    const previewSummary = canApplyPreviewSummary ? previewBundle.previewSummary : null;
    const totalsForPricing = {
      nonAutoTotal: Number(cartTotals.nonAutoTotal || 0),
      autoEligibleTotal: Number(cartTotals.autoEligibleTotal || 0),
    };
    const giftRewardDiscount = calculateCartGiftRewardDisplayDiscount(cartItems, totalsForPricing);
    const subtotalBeforeDiscountRaw = previewSummary
      ? roundPrice(Number(previewSummary.subtotal || 0))
      : roundPrice(Number(cartTotals.totalBeforeDiscount || cartTotals.total || 0));
    const itemsTotal = previewSummary
      ? roundPrice(Number(previewSummary.items_total || 0))
      : roundPrice(Number(cartTotals.total || 0));
    const discountAmountRaw = previewSummary
      ? roundPrice(Number(previewSummary.discount_total || 0))
      : roundPrice(Math.max(0, subtotalBeforeDiscountRaw - itemsTotal));
    const subtotalBeforeDiscount = roundPrice(
      Math.max(0, Number(subtotalBeforeDiscountRaw || 0) - Number(giftRewardDiscount || 0))
    );
    let discountAmount = roundPrice(
      Math.max(0, Number(discountAmountRaw || 0) - Number(giftRewardDiscount || 0))
    );
    const orderLevelDiscount = roundPrice(Math.max(0, Number(cartTotals.total || 0) - itemsTotal));
    const selectedBenefitTitles = getCartPricingSelectedBenefitTitles(
      previewBundle.localPreviewData || previewBundle.previewData
    );
    const discountDetails = buildCartPricingDiscountDetails({
      previewSummary,
      cartItems,
      totalsForPricing,
      actualDiscount: discountAmountRaw,
      orderLevelDiscount,
      giftRewardDiscount,
      selectedBenefitTitles,
    });

    const defaultDeliverySettings = getCartPricingCachedDeliverySettings();
    const deliveryQuote = str(methodCode || "").trim() === "delivery"
      ? getCartPricingCachedDeliveryQuote(itemsTotal)
      : null;
    const deliveryState = resolveCartPricingDeliveryState(
      itemsTotal,
      methodCode,
      deliveryQuote,
      defaultDeliverySettings
    );
    const paymentState = resolveCartPricingPaymentState(draft);
    const lineStates = buildCartPricingLineStates(
      cartItems,
      itemsTotal,
      canApplyPreviewSummary ? (previewBundle.localPreviewData || previewBundle.previewData || null) : null,
      { allowOrderDiscountDistribution: canApplyPreviewSummary }
    );
    const bonusLevel = getCartBonusActiveLevel();
    const bonusRedeemAvailableAmount = bonusLevel
      ? calculateCartBonusRedeemAmount(itemsTotal, bonusLevel)
      : 0;
    const bonusRedeemEnabled = !!state.cartBonusRedeemEnabled && bonusRedeemAvailableAmount > 0;
    const bonusRedeemAmount = bonusRedeemEnabled ? bonusRedeemAvailableAmount : 0;
    const displayLineStates = buildCartPricingBonusRedeemDisplayLineStates(lineStates, bonusRedeemAmount);
    const baseDiscountDetailItems = Array.isArray(discountDetails.items) ? discountDetails.items : [];
    const discountDetailItems = bonusRedeemAmount > 0
      ? [
          ...baseDiscountDetailItems,
          {
            key: "bonus_redeem",
            title: state.homeBonusConfig?.settings?.bonus_coin_name || "Бонусы",
            amount: bonusRedeemAmount,
            sourceKind: "bonus",
            promoCode: null,
          },
        ]
      : baseDiscountDetailItems;
    const finalDiscountAmount = bonusRedeemAmount > 0
      ? roundPrice(discountAmount + bonusRedeemAmount)
      : discountAmount;
    const total = roundPrice(
      Math.max(0, Number(itemsTotal || 0) - Number(bonusRedeemAmount || 0))
      + (deliveryState.isDelivery ? Number(deliveryState.cost || 0) : 0)
    );
    const changeState = resolveCartPricingChangeState(draft, total, paymentState.code);
    const bonusAccrualAmount = bonusLevel
      ? calculateCartBonusPreview(cartItems, lineStates, itemsTotal, bonusLevel)
      : 0;
    const allowRedeemAndAccrue = Number(state.homeBonusConfig?.settings?.allow_redeem_and_accrue || 0) === 1;
    const bonusAccrualBlockedByRedeem = bonusRedeemEnabled && !allowRedeemAndAccrue && bonusAccrualAmount > 0;

    return {
      visible: true,
      methodCode,
      isDelivery: deliveryState.isDelivery,
      subtotalBeforeDiscount,
      itemsTotal,
      discountAmount: finalDiscountAmount,
      deliveryCost: Number(deliveryState.cost || 0),
      deliveryFreeNote: deliveryState.freeNote,
      deliveryMinNote: deliveryState.minNote,
      paymentTitle: paymentState.title,
      changeFrom: changeState.changeFrom,
      changeAmount: changeState.changeAmount,
      total,
      deliveryQuote,
      defaultDeliverySettings,
      discountDetailItems,
      discountDetailNote: discountDetails.note,
      bonusAccrualAmount,
      bonusRedeemEnabled,
      bonusRedeemAvailableAmount,
      bonusRedeemAmount,
      bonusAccrualBlockedByRedeem,
      lineStates,
      displayLineStates,
    };
  }

  function buildCartPricingSnapshot() {
    const key = buildCartPricingLiveKey();
    if (key && cartPricingSnapshotCacheKey === key && cartPricingSnapshotCacheValue) {
      return cartPricingSnapshotCacheValue;
    }
    const snapshot = buildCartPricingSnapshotUncached();
    cartPricingSnapshotCacheKey = key;
    cartPricingSnapshotCacheValue = snapshot;
    return snapshot;
  }

  function applyCartPricingCheckoutTotals(summaryState = null) {
    const cartItems = cartItemsResolved();
    const hasItems = Array.isArray(cartItems) && cartItems.length > 0;
    const fallbackTotal = roundPrice(Number(computeCartTotals(cartItems).total || 0));
    const snapshotTotalRaw = summaryState && summaryState.visible !== false
      ? Number(summaryState?.total || 0)
      : NaN;
    const displayTotal = Number.isFinite(snapshotTotalRaw)
      ? roundPrice(snapshotTotalRaw)
      : fallbackTotal;

    if (elCartTotal) {
      elCartTotal.textContent = money(displayTotal);
    }

    if (elCheckoutBtn) {
      elCheckoutBtn.disabled = !hasItems;
      const totalSpan = $("#shopCartTotal", elCheckoutBtn) || $(".shop-checkout-total", elCheckoutBtn);
      if (totalSpan) totalSpan.textContent = money(displayTotal);
    }

    if (elMobileCheckoutBtn) {
      elMobileCheckoutBtn.disabled = !hasItems;
    }
    if (elMobileCartTotal) {
      elMobileCartTotal.textContent = money(displayTotal);
    }

    if (openCartSheetCtx) {
      if (openCartSheetCtx.checkoutBtn) {
        openCartSheetCtx.checkoutBtn.disabled = !hasItems;
        const totalSpan = $(".shop-sheet-checkout-total", openCartSheetCtx.checkoutBtn);
        if (totalSpan) totalSpan.textContent = money(displayTotal);
      }
      if (openCartSheetCtx.totalEl) {
        openCartSheetCtx.totalEl.textContent = money(displayTotal);
      }
    }

    return displayTotal;
  }

  async function buildCartPricingSummaryState(opts = {}) {
    const cartItems = cartItemsResolved();
    if (!Array.isArray(cartItems) || !cartItems.length) {
      return {
        visible: false,
        lineStates: [],
      };
    }

    const draft = loadCheckoutDraft();
    const methodCode = resolveCartPricingMethodCode(draft);
    const previewRequest = buildCheckoutBenefitsPreviewRequest({
      items: cartItems,
      methodCode,
      promoCode: draft?.promo_code || "",
      selectedDiscountId: draft?.selected_discount_id,
      selectedDiscountSource: draft?.selected_discount_source,
      selectedPromoSource: draft?.selected_promo_source,
      selectedPromoRewardId: draft?.selected_promo_reward_id,
    });
    const token = typeof getCustomerToken === "function"
      ? str(getCustomerToken() || "").trim()
      : "";
    const forceBenefits = opts?.forceBenefits === true;
    const hydrateBenefits = opts?.hydrateBenefits !== false;
    if (token && hydrateBenefits) {
      try {
        await ensureBenefitsStoreHydrated({
          previewRequest,
          force: forceBenefits,
          warmDetails: false,
        });
      } catch (_) {}
    }

    invalidateCartPricingSnapshotCache();
    const summaryState = buildCartPricingSnapshot();
    if (!summaryState || summaryState.visible === false) {
      return summaryState;
    }
    const bonusLevel = await ensureCartBonusPreviewLevel();
    if (bonusLevel) {
      summaryState.bonusAccrualAmount = calculateCartBonusPreview(
        cartItems,
        summaryState.lineStates,
        summaryState.itemsTotal,
        bonusLevel
      );
      const bonusRedeemAvailableAmount = calculateCartBonusRedeemAmount(summaryState.itemsTotal, bonusLevel);
      const bonusRedeemEnabled = !!state.cartBonusRedeemEnabled && bonusRedeemAvailableAmount > 0;
      const bonusRedeemAmount = bonusRedeemEnabled ? bonusRedeemAvailableAmount : 0;
      const baseDiscountAmount = roundPrice(Math.max(
        0,
        Number(summaryState.discountAmount || 0) - Number(summaryState.bonusRedeemAmount || 0)
      ));
      const baseDiscountDetails = Array.isArray(summaryState.discountDetailItems)
        ? summaryState.discountDetailItems.filter((entry) => str(entry?.key || "").trim() !== "bonus_redeem")
        : [];
      summaryState.discountAmount = roundPrice(baseDiscountAmount + bonusRedeemAmount);
      summaryState.discountDetailItems = bonusRedeemAmount > 0
        ? [
            ...baseDiscountDetails,
            {
              key: "bonus_redeem",
              title: state.homeBonusConfig?.settings?.bonus_coin_name || "Бонусы",
              amount: bonusRedeemAmount,
              sourceKind: "bonus",
              promoCode: null,
            },
          ]
        : baseDiscountDetails;
      summaryState.bonusRedeemEnabled = bonusRedeemEnabled;
      summaryState.bonusRedeemAvailableAmount = bonusRedeemAvailableAmount;
      summaryState.bonusRedeemAmount = bonusRedeemAmount;
      summaryState.displayLineStates = buildCartPricingBonusRedeemDisplayLineStates(
        summaryState.lineStates,
        bonusRedeemAmount
      );
      summaryState.bonusAccrualBlockedByRedeem = (
        summaryState.bonusRedeemEnabled
        && Number(state.homeBonusConfig?.settings?.allow_redeem_and_accrue || 0) !== 1
        && Number(summaryState.bonusAccrualAmount || 0) > 0
      );
    }
    if (str(methodCode || "").trim() !== "delivery") {
      return summaryState;
    }

    let deliveryQuote = summaryState?.deliveryQuote || null;
    let defaultDeliverySettings = summaryState?.defaultDeliverySettings || getCartPricingCachedDeliverySettings();
    try {
      deliveryQuote = await getDeliveryQuote(summaryState.itemsTotal);
    } catch (_) {}
    if (
      !defaultDeliverySettings &&
      (!deliveryQuote || (
        deliveryQuote?.delivery_cost == null
        && deliveryQuote?.free_delivery_from == null
        && deliveryQuote?.min_order_amount == null
      ))
    ) {
      try {
        defaultDeliverySettings = await getDeliverySettings();
      } catch (_) {}
    }

    const deliveryState = resolveCartPricingDeliveryState(
      summaryState.itemsTotal,
      methodCode,
      deliveryQuote,
      defaultDeliverySettings
    );
    const total = roundPrice(
      Math.max(0, Number(summaryState.itemsTotal || 0) - Number(summaryState.bonusRedeemAmount || 0))
      + (deliveryState.isDelivery ? Number(deliveryState.cost || 0) : 0)
    );
    const paymentCode = str(draft?.payment_code || "").trim();
    const changeState = resolveCartPricingChangeState(draft, total, paymentCode);

    return {
      ...summaryState,
      isDelivery: deliveryState.isDelivery,
      deliveryCost: Number(deliveryState.cost || 0),
      deliveryFreeNote: deliveryState.freeNote,
      deliveryMinNote: deliveryState.minNote,
      changeFrom: changeState.changeFrom,
      changeAmount: changeState.changeAmount,
      total,
      deliveryQuote,
      defaultDeliverySettings,
    };
  }

  function getConnectedCartPricingSummarySections() {
    return Array.from(document.querySelectorAll(".shop-cart-pricing-summary-section"))
      .filter((node) => node && node.isConnected);
  }

  function applyCartPricingStateToSummarySections(summaryState = null, sections = null, options = {}) {
    const effectiveSummaryState = summaryState && typeof summaryState === "object"
      ? summaryState
      : buildCartPricingSnapshot();
    const targetSections = Array.isArray(sections) ? sections : getConnectedCartPricingSummarySections();
    if (!targetSections.length) return effectiveSummaryState;
    const updateLineStates = options?.updateLineStates !== false;
    targetSections.forEach((section) => {
      renderCartPricingSummarySection(section, effectiveSummaryState);
      const listEl = section.parentElement;
      const displayLineStates = Array.isArray(effectiveSummaryState?.displayLineStates)
        ? effectiveSummaryState.displayLineStates
        : effectiveSummaryState?.lineStates;
      if (updateLineStates && listEl && Array.isArray(displayLineStates)) {
        applyCartPricingLineStatesToList(listEl, displayLineStates);
      }
    });
    return effectiveSummaryState;
  }

  function applyCartPricingLineStatesToConnectedRows(summaryState = null) {
    const effectiveSummaryState = summaryState && typeof summaryState === "object"
      ? summaryState
      : buildCartPricingSnapshot();
    const displayLineStates = Array.isArray(effectiveSummaryState?.displayLineStates)
      ? effectiveSummaryState.displayLineStates
      : effectiveSummaryState?.lineStates;
    if (!Array.isArray(displayLineStates) || !displayLineStates.length) return effectiveSummaryState;
    applyCartPricingLineStatesToList(document, displayLineStates);
    return effectiveSummaryState;
  }

  function updateCartBonusRedeemSections(summaryState = null) {
    const safeState = summaryState && typeof summaryState === "object" ? summaryState : buildCartPricingSnapshot();
    let amount = Math.floor(Math.max(0, Number(safeState?.bonusRedeemAvailableAmount || 0)));
    if (amount > 0) {
      state.cartBonusRedeemAvailableAmount = amount;
    }
    document.querySelectorAll(".shop-cart-bonus-redeem-section").forEach((section) => {
      const accrualAmount = Math.floor(Math.max(0, Number(safeState?.bonusAccrualAmount || 0)));
      const allowRedeemAndAccrue = Number(state.homeBonusConfig?.settings?.allow_redeem_and_accrue || 0) === 1;
      const balance = Math.max(0, Number(state.homeBonusConfig?.account?.balance || 0));
      const hasBalance = balance > 0;
      const canRedeemAmount = amount > 0;
      if (!hasBalance && state.cartBonusRedeemEnabled) {
        state.cartBonusRedeemEnabled = false;
      }
      const redeemActive = !!state.cartBonusRedeemEnabled && hasBalance && canRedeemAmount;
      section.querySelectorAll("[data-cart-bonus-redeem-available]").forEach((node) => {
        node.textContent = money(amount);
      });
      section.querySelectorAll("[data-cart-bonus-accrual-amount]").forEach((node) => {
        node.innerHTML = `+${formatShopBonusMoney(accrualAmount)}`;
      });
      section.querySelectorAll("[data-cart-bonus-redeem-button-amount]").forEach((node) => {
        const accrualHtml = allowRedeemAndAccrue && accrualAmount > 0
          ? ` <span class="shop-cart-bonus-action-pill__delta">+${formatShopBonusMoney(accrualAmount)}</span>`
          : "";
        node.innerHTML = `-${formatShopBonusMoney(amount)}${accrualHtml}`;
      });
      section.querySelectorAll("[data-cart-bonus-redeem-label]").forEach((node) => {
        node.textContent = allowRedeemAndAccrue ? "Списать и начислить" : "Списать";
      });
      section.querySelectorAll("[data-cart-bonus-redeem-toggle]").forEach((input) => {
        const disabled = !hasBalance;
        input.disabled = disabled;
        input.checked = redeemActive;
        input.closest(".shop-cart-bonus-redeem-switch")?.classList.toggle("is-disabled", disabled);
      });
      section.querySelectorAll("[data-cart-bonus-redeem-button]").forEach((button) => {
        const disabled = !hasBalance || !canRedeemAmount;
        button.disabled = disabled;
        button.classList.toggle("is-disabled", disabled);
        button.classList.toggle("is-active", redeemActive);
      });
      section.querySelectorAll("[data-cart-bonus-accrual-button]").forEach((button) => {
        button.disabled = false;
        button.classList.remove("is-disabled");
        button.classList.toggle("is-active", !redeemActive);
      });
    });
  }

  function captureCartBonusRedeemScrollState() {
    const containers = [];
    const seen = new Set();
    const addContainer = (node) => {
      if (!node || seen.has(node)) return;
      seen.add(node);
      containers.push(node);
    };

    document.querySelectorAll(".shop-cart-bonus-redeem-section").forEach((section) => {
      addContainer(section.closest(".shop-cart-list"));
      addContainer(section.closest(".shop-cart-sheet"));
      addContainer(section.closest(".app-modal-body"));
    });

    return containers.map((node) => ({
      node,
      left: Math.max(0, Number(node.scrollLeft || 0)),
      top: Math.max(0, Number(node.scrollTop || 0)),
    }));
  }

  function restoreCartBonusRedeemScrollState(scrollState) {
    const entries = Array.isArray(scrollState) ? scrollState : [];
    if (!entries.length) return;

    const restore = () => {
      entries.forEach((entry) => {
        const node = entry?.node;
        if (!node || !node.isConnected) return;
        node.scrollLeft = Math.max(0, Number(entry.left || 0));
        node.scrollTop = Math.max(0, Number(entry.top || 0));
        if (node.matches?.(".shop-cart-list") && typeof window.syncShopCartModeHeaderSticky === "function") {
          window.syncShopCartModeHeaderSticky(node, { forceExpand: Number(entry.top || 0) <= 6 });
        }
      });
    };

    restore();
    requestAnimationFrame(() => {
      restore();
      requestAnimationFrame(restore);
    });
  }

  let cartBonusRedeemPreToggleScrollState = null;

  function rememberCartBonusRedeemScrollBeforeToggle(event) {
    const target = event?.target;
    if (!target || typeof target.closest !== "function") return;
    if (!target.closest(".shop-cart-bonus-redeem-section")) return;
    cartBonusRedeemPreToggleScrollState = captureCartBonusRedeemScrollState();
  }

  ["pointerdown", "mousedown", "touchstart"].forEach((eventName) => {
    document.addEventListener(eventName, rememberCartBonusRedeemScrollBeforeToggle, {
      capture: true,
      passive: true,
    });
  });
  document.addEventListener("keydown", (event) => {
    const key = str(event?.key || "").trim();
    if (key !== " " && key !== "Enter") return;
    rememberCartBonusRedeemScrollBeforeToggle(event);
  }, true);

  function applyCartPricingStateImmediately(summaryState = null) {
    const effectiveSummaryState = summaryState && typeof summaryState === "object"
      ? summaryState
      : buildCartPricingSnapshot();
    applyCartPricingCheckoutTotals(effectiveSummaryState);
    syncCartBenefitsServiceBlocksUi();
    applyCartPricingStateToSummarySections(effectiveSummaryState);
    applyCartPricingLineStatesToConnectedRows(effectiveSummaryState);
    updateCartBonusRedeemSections(effectiveSummaryState);
    return effectiveSummaryState;
  }

  function refreshCartPricingLocalUi() {
    let summaryState = null;
    try {
      summaryState = buildCartPricingSnapshot();
    } catch (error) {
      console.warn("Failed to build cart pricing state for bonus redeem:", error);
      return null;
    }
    try {
      applyCartPricingCheckoutTotals(summaryState);
    } catch (error) {
      console.warn("Failed to update cart totals for bonus redeem:", error);
    }
    getConnectedCartPricingSummarySections().forEach((section) => {
      try {
        renderCartPricingSummarySection(section, summaryState);
      } catch (error) {
        console.warn("Failed to render cart summary for bonus redeem:", error);
      }
    });
    try {
      updateCartBonusRedeemSections(summaryState);
    } catch (error) {
      console.warn("Failed to update bonus redeem section:", error);
    }
    return summaryState;
  }

  function refreshCartPricingSummarySectionsTextUi(summaryState = null) {
    const snapshot = summaryState && typeof summaryState === "object" ? summaryState : buildCartPricingSnapshot();
    if (!snapshot || snapshot.visible === false) return snapshot;

    const updateRowByLabel = (root, labelText, valueText, display = "") => {
      if (!root) return;
      const rows = Array.from(root.querySelectorAll(".shop-order-summary-row"));
      const row = rows.find((entry) => str(entry.querySelector(".shop-order-summary-label")?.textContent || "").trim() === labelText);
      if (!row) return;
      const value = row.querySelector(".shop-order-summary-value");
      if (value) value.textContent = valueText;
      row.style.display = display;
    };

    getConnectedCartPricingSummarySections().forEach((section) => {
      const summary = section.querySelector(".shop-order-summary");
      if (!summary) return;
      section.classList.remove("hidden");
      updateRowByLabel(summary, "Стоимость доставки", money(snapshot.deliveryCost || 0), snapshot.isDelivery ? "" : "none");
      updateRowByLabel(summary, "Сумма товаров", money(snapshot.subtotalBeforeDiscount || 0));
      updateRowByLabel(summary, "Скидка", `-${money(snapshot.discountAmount || 0)}`, Number(snapshot.discountAmount || 0) > 0 ? "" : "none");
      const coinName = state.homeBonusConfig?.settings?.bonus_coin_name || "Бонусы";
      updateRowByLabel(summary, coinName, `+${formatShopBonusNumber(snapshot.bonusAccrualAmount || 0)} ${getShopBonusCoinIconHtml('1em', '2px')}`, Number(snapshot.bonusAccrualAmount || 0) > 0 ? "" : "none");
      const totalValue = summary.querySelector(".shop-order-summary-total-value");
      if (totalValue) totalValue.textContent = money(snapshot.total || 0);
    });

    return snapshot;
  }

  function resetCartBonusRedeemScrollPosition() {
    const lists = Array.from(document.querySelectorAll(".shop-cart-bonus-redeem-section"))
      .map((section) => section.closest(".shop-cart-list"))
      .filter(Boolean);
    if (!lists.length) return;
    const restore = () => {
      lists.forEach((list) => {
        if (!list?.isConnected) return;
        list.scrollTop = 0;
        if (typeof window.syncShopCartModeHeaderSticky === "function") {
          window.syncShopCartModeHeaderSticky(list, { forceExpand: true });
        }
      });
    };
    restore();
    requestAnimationFrame(() => {
      restore();
      requestAnimationFrame(restore);
    });
  }

  function refreshCartBonusRedeemUi() {
    const scrollState = cartBonusRedeemPreToggleScrollState || captureCartBonusRedeemScrollState();
    cartBonusRedeemPreToggleScrollState = null;
    invalidateCartPricingSnapshotCache();
    let summaryState = null;
    try {
      summaryState = buildCartPricingSnapshot();
    } catch (error) {
      console.warn("Failed to build cart pricing state for bonus redeem:", error);
      return null;
    }
    try {
      applyCartPricingCheckoutTotals(summaryState);
    } catch (error) {
      console.warn("Failed to update cart totals for bonus redeem:", error);
    }
    try {
      applyCartPricingStateToSummarySections(summaryState, null, { updateLineStates: false });
    } catch (error) {
      console.warn("Failed to update cart summary for bonus redeem:", error);
    }
    try {
      applyCartPricingLineStatesToConnectedRows(summaryState);
    } catch (error) {
      console.warn("Failed to update cart lines for bonus redeem:", error);
    }
    try {
      updateCartBonusRedeemSections(summaryState);
      restoreCartBonusRedeemScrollState(scrollState);
    } catch (error) {
      console.warn("Failed to update bonus redeem section:", error);
    }
    try {
      if (typeof window.refreshOpenShopCheckoutPricingUi === "function") {
        window.refreshOpenShopCheckoutPricingUi(summaryState);
      }
    } catch (error) {
      console.warn("Failed to update checkout pricing for bonus redeem:", error);
    }
    return summaryState;
  }

  function buildCartPricingLiveKey(cartItems = null, draft = null) {
    const safeItems = Array.isArray(cartItems) ? cartItems : cartItemsResolved();
    const safeDraft = draft && typeof draft === "object" ? draft : loadCheckoutDraft();
    const normalizedItems = (Array.isArray(safeItems) ? safeItems : [])
      .map((item) => ({
        key: str(item?.key || "").trim(),
        product_id: Number(item?.product_id || item?.product?.id || 0) || 0,
        combo_id: Number(item?.combo_id || 0) || 0,
        type: str(item?.type || "").trim(),
        qty: Math.max(0, Number(item?.qty || 0)),
        line_total: roundPrice(Number(item?.line_total || 0) || 0),
      }))
      .filter((entry) => entry.key && entry.qty > 0)
      .sort((a, b) => a.key.localeCompare(b.key));
    const token = typeof getCustomerToken === "function"
      ? str(getCustomerToken() || "").trim()
      : "";
    const customerCache = typeof getCustomerCache === "function" ? getCustomerCache() : null;
    let addressId = 0;
    try {
      addressId = Number(state?.selectedAddress?.id || 0) || 0;
    } catch {}
    return JSON.stringify({
      items: normalizedItems,
      tokenPresent: !!token,
      customerId: Number(customerCache?.id || 0) || 0,
      methodCode: resolveCartPricingMethodCode(safeDraft),
      addressId,
      promoCode: normalizeCheckoutBenefitsPromoInputValue(safeDraft?.promo_code || "", { trim: true }),
      selectedDiscountId: normalizeCheckoutSelectedDiscountId(safeDraft?.selected_discount_id),
      selectedDiscountSource: normalizeCheckoutDiscountSource(safeDraft?.selected_discount_source),
      selectedPromoSource: normalizeCheckoutPromoSource(safeDraft?.selected_promo_source),
      selectedPromoRewardId: normalizeCheckoutSelectedDiscountId(safeDraft?.selected_promo_reward_id),
      bonusRedeemEnabled: !!state.cartBonusRedeemEnabled,
      bonusRedeemChoiceVersion: Number(state.cartBonusRedeemChoiceVersion || 0),
    });
  }

  let cartPricingAsyncRefreshTimer = 0;
  let cartPricingAsyncRefreshRunning = false;
  let cartPricingAsyncRefreshPending = false;
  let cartPricingAsyncRefreshSeq = 0;
  let cartPricingAsyncRefreshDelayMs = 160;
  let cartPricingSettleTimer = 0;
  let cartPricingSettleRunning = false;
  let cartPricingSettleSeq = 0;
  let cartPricingSettleDelayMs = 160;

  async function runQueuedCartPricingAsyncRefresh() {
    if (cartPricingAsyncRefreshRunning) return null;
    cartPricingAsyncRefreshRunning = true;
    try {
      let appliedState = null;
      while (cartPricingAsyncRefreshPending) {
        cartPricingAsyncRefreshPending = false;
        const runSeq = cartPricingAsyncRefreshSeq;
        const runKey = buildCartPricingLiveKey();
        let summaryState = null;
        try {
          summaryState = await buildCartPricingSummaryState({
            forceBenefits: false,
            hydrateBenefits: false,
          });
        } catch (error) {
          console.warn("Failed to refresh cart pricing summary:", error);
          summaryState = buildCartPricingSnapshot();
        }
        if (runSeq !== cartPricingAsyncRefreshSeq) {
          continue;
        }
        if (runKey !== buildCartPricingLiveKey()) {
          continue;
        }
        appliedState = applyCartPricingStateImmediately(summaryState);
        if (typeof applyDeliveryProgressSnapshot === "function") {
          applyDeliveryProgressSnapshot(appliedState);
        }
      }
      return appliedState;
    } finally {
      cartPricingAsyncRefreshRunning = false;
      if (cartPricingAsyncRefreshPending && !cartPricingAsyncRefreshTimer) {
        cartPricingAsyncRefreshTimer = window.setTimeout(() => {
          cartPricingAsyncRefreshTimer = 0;
          void runQueuedCartPricingAsyncRefresh();
        }, cartPricingAsyncRefreshDelayMs);
      }
    }
  }

  function queueCartPricingAsyncRefresh(reason = "", delayMs = 80) {
    if (!reason) {
      // keep interface flexible for silent callers
    }
    cartPricingAsyncRefreshDelayMs = Math.max(0, Number(delayMs || 0));
    cartPricingAsyncRefreshPending = true;
    cartPricingAsyncRefreshSeq += 1;
    if (cartPricingAsyncRefreshTimer) {
      window.clearTimeout(cartPricingAsyncRefreshTimer);
    }
    cartPricingAsyncRefreshTimer = window.setTimeout(() => {
      cartPricingAsyncRefreshTimer = 0;
      void runQueuedCartPricingAsyncRefresh();
    }, Math.max(0, Number(delayMs || 0)));
    return Promise.resolve(null);
  }

  async function runCartPricingSettle(seq, expectedKey) {
    if (cartPricingSettleRunning) {
      if (seq === cartPricingSettleSeq) {
        queueCartPricingSettle("settle-running", cartPricingSettleDelayMs);
      }
      return null;
    }

    cartPricingSettleRunning = true;
    try {
      if (seq !== cartPricingSettleSeq) return null;
      const runKey = str(expectedKey || buildCartPricingLiveKey()).trim();
      let summaryState = null;
      try {
        summaryState = await buildCartPricingSummaryState({
          forceBenefits: false,
          hydrateBenefits: true,
        });
      } catch (error) {
        console.warn("Failed to settle cart pricing summary:", error);
        summaryState = buildCartPricingSnapshot();
      }
      if (seq !== cartPricingSettleSeq) return null;
      if (runKey && runKey !== buildCartPricingLiveKey()) {
        queueCartPricingSettle("settle-key-changed", cartPricingSettleDelayMs);
        return null;
      }
      const appliedState = applyCartPricingStateImmediately(summaryState);
      if (typeof applyDeliveryProgressSnapshot === "function") {
        applyDeliveryProgressSnapshot(appliedState);
      }
      return appliedState;
    } finally {
      cartPricingSettleRunning = false;
      if (seq !== cartPricingSettleSeq && !cartPricingSettleTimer) {
        queueCartPricingSettle("settle-after-running", cartPricingSettleDelayMs);
      }
    }
  }

  function queueCartPricingSettle(reason = "", delayMs = 160) {
    if (!reason) {
      // keep interface flexible for silent callers
    }
    cartPricingSettleDelayMs = Math.max(0, Number(delayMs || 0));
    const seq = ++cartPricingSettleSeq;
    if (cartPricingSettleTimer) {
      window.clearTimeout(cartPricingSettleTimer);
    }
    cartPricingSettleTimer = window.setTimeout(() => {
      cartPricingSettleTimer = 0;
      void runCartPricingSettle(seq, buildCartPricingLiveKey());
    }, cartPricingSettleDelayMs);
    return Promise.resolve(null);
  }

  async function syncCartPricingSummaryUi(opts = {}) {
    const summaryState = applyCartPricingStateImmediately(buildCartPricingSnapshot());
    if (typeof applyDeliveryProgressSnapshot === "function") {
      applyDeliveryProgressSnapshot(summaryState);
    }
    const reason = str(opts?.reason || "").trim();
    const delayMs = reason === "changeQty.light" || reason === "updateCartTotalsUiOnly"
      ? 180
      : 120;
    queueCartPricingSettle("syncCartPricingSummaryUi", delayMs);
    return summaryState;
  }

  let cartPricingSummaryUiFrame = 0;
  let cartPricingSummaryUiQueuedReason = "";

  function queueCartPricingSummaryUi(reason = "cart") {
    cartPricingSummaryUiQueuedReason = str(reason || cartPricingSummaryUiQueuedReason || "cart").trim() || "cart";
    if (cartPricingSummaryUiFrame) return Promise.resolve(null);
    const scheduleFrame = typeof window.requestAnimationFrame === "function"
      ? window.requestAnimationFrame.bind(window)
      : (fn) => window.setTimeout(fn, 16);
    cartPricingSummaryUiFrame = scheduleFrame(() => {
      cartPricingSummaryUiFrame = 0;
      const queuedReason = cartPricingSummaryUiQueuedReason;
      cartPricingSummaryUiQueuedReason = "";
      Promise.resolve(syncCartPricingSummaryUi({ reason: queuedReason })).catch(() => {});
    });
    return Promise.resolve(null);
  }

  window.syncShopCartPricingSummaryUi = syncCartPricingSummaryUi;
  window.queueShopCartPricingSummaryUi = queueCartPricingSummaryUi;
  window.refreshShopCartPricingLocalUi = refreshCartPricingLocalUi;
  window.refreshShopCartBonusRedeemUi = refreshCartBonusRedeemUi;
  window.invalidateShopCartPricingSnapshotCache = invalidateCartPricingSnapshotCache;
  window.applyShopCartPricingTotalsToButtons = applyCartPricingCheckoutTotals;
  window.getShopCartPricingSnapshot = buildCartPricingSnapshot;

  function resolveCheckoutBenefitsSelectedPromoFromPreview(previewData) {
    const selectedPromoCard = Array.isArray(previewData?.promo_codes)
      ? previewData.promo_codes.find((entry) => entry?.is_selected)
      : null;
    const selectedPromoSource = selectedPromoCard
      ? (normalizeCheckoutPromoSource(selectedPromoCard?.source) || "promo_code")
      : null;
    return {
      card: selectedPromoCard || null,
      promoCode: selectedPromoCard ? str(selectedPromoCard?.code || "").trim() : "",
      selectedPromoSource,
      selectedPromoRewardId: selectedPromoCard && selectedPromoSource === "reward_promo"
        ? normalizeCheckoutSelectedDiscountId(selectedPromoCard?.reward_id || selectedPromoCard?.id)
        : null,
    };
  }

  function findCheckoutBenefitsPromoCardBySelection(previewData, {
    promoCode,
    selectedPromoSource,
    selectedPromoRewardId,
  } = {}) {
    const normalizedPromoCode = str(promoCode || "").trim();
    const normalizedPromoSource = normalizeCheckoutPromoSource(selectedPromoSource)
      || (normalizedPromoCode ? "promo_code" : null);
    const normalizedPromoRewardId = normalizeCheckoutSelectedDiscountId(selectedPromoRewardId);
    if (!normalizedPromoSource) return null;
    const promoCards = Array.isArray(previewData?.promo_codes) ? previewData.promo_codes : [];
    return promoCards.find((entry) => {
      const entrySource = normalizeCheckoutPromoSource(entry?.source) || "promo_code";
      if (entrySource !== normalizedPromoSource) return false;
      if (entrySource === "reward_promo") {
        return normalizeCheckoutSelectedDiscountId(entry?.reward_id || entry?.id) === normalizedPromoRewardId;
      }
      return str(entry?.code || "").trim() === normalizedPromoCode;
    }) || null;
  }

  function getCheckoutBenefitsPromoInvalidationMessage(item) {
    const disabledReason = str(item?.disabled_reason || "").trim();
    if (disabledReason) return disabledReason;
    return "Условие промокода больше не выполняется.";
  }

  async function fetchCheckoutBenefitsPreview(previewRequest, {
    force = false,
  } = {}) {
    const token = typeof getCustomerToken === "function"
      ? str(getCustomerToken() || "").trim()
      : "";
    if (!token) return null;

    const cacheKey = buildCheckoutBenefitsPreviewCacheKey(previewRequest);
    if (cacheKey) {
      const cached = !force ? peekCheckoutBenefitsPreviewCache(previewRequest) : null;
      if (cached) return cached;
      const inflight = checkoutBenefitsClientCache.previewPromises.get(cacheKey);
      if (inflight) return inflight;
    }

    const requestPromise = (async () => {
      try {
        const res = await apiJson("/api/public/checkout/benefits/preview", {
          method: "POST",
          body: previewRequest && typeof previewRequest === "object" ? previewRequest : {},
        });
        if (!res || res.ok === false) return null;
        const data = res.data && typeof res.data === "object" ? res.data : null;
        return storeCheckoutBenefitsPreviewCache(previewRequest, data);
      } catch (err) {
        if (String(err?.message || "").includes("UNAUTHORIZED")) {
          if (typeof clearCustomer === "function") clearCustomer();
          return null;
        }
        console.error("Failed to load checkout benefits preview:", err);
        return null;
      } finally {
        if (cacheKey) checkoutBenefitsClientCache.previewPromises.delete(cacheKey);
      }
    })();

    if (cacheKey) checkoutBenefitsClientCache.previewPromises.set(cacheKey, requestPromise);
    try {
      return await requestPromise;
    } catch {
      return null;
    }
  }

  async function attachCheckoutBenefitsPromoCode(rawCode) {
    const normalizedCode = normalizeCheckoutBenefitsPromoInputValue(rawCode || "", { trim: true });
    if (!normalizedCode) {
      throw new Error("PROMO_CODE_REQUIRED");
    }
    try {
      const res = await apiJson("/api/public/checkout/benefits/attach-promo", {
        method: "POST",
        body: { code: normalizedCode },
      });
      const data = res?.data && typeof res.data === "object" ? res.data : {};
      return {
        code: str(data?.code || normalizedCode).trim() || normalizedCode,
        promoCodeId: normalizeCheckoutSelectedDiscountId(data?.promo_code_id),
        discountId: normalizeCheckoutSelectedDiscountId(data?.discount_id),
        visibility: str(data?.visibility || "").trim().toLowerCase() === "hidden" ? "hidden" : "public",
      };
    } catch (err) {
      if (String(err?.message || "").includes("UNAUTHORIZED")) {
        if (typeof clearCustomer === "function") clearCustomer();
      }
      throw err;
    }
  }

  const desktopCheckoutBenefitsState = {
    sourceScreen: "cart",
    promoInputValue: "",
  };

  function normalizeCheckoutBenefitsSourceScreen(value, fallback = "checkout") {
    const normalized = str(value || "").trim().toLowerCase();
    if (
      normalized === "cart"
      || normalized === "cart-service"
      || normalized === "checkout"
      || normalized === "bonus-level"
      || normalized === "home-site-menu"
      || normalized === "nav"
    ) {
      return normalized;
    }
    return fallback;
  }

  function getActiveCheckoutBenefitsSourceScreen(fallback = "checkout") {
    const sheetSource = hasLiveCartSheetContext()
      ? str(openCartSheetCtx?.benefitsSourceScreen || "").trim().toLowerCase()
      : "";
    if (
      sheetSource === "cart"
      || sheetSource === "cart-service"
      || sheetSource === "checkout"
      || sheetSource === "bonus-level"
      || sheetSource === "home-site-menu"
      || sheetSource === "nav"
    ) {
      return sheetSource;
    }
    const desktopSource = str(desktopCheckoutBenefitsState.sourceScreen || "").trim().toLowerCase();
    if (
      desktopSource === "cart"
      || desktopSource === "cart-service"
      || desktopSource === "checkout"
      || desktopSource === "bonus-level"
      || desktopSource === "home-site-menu"
      || desktopSource === "nav"
    ) {
      return desktopSource;
    }
    return fallback;
  }

  function isDesktopBenefitsHostActive() {
    return Boolean(
      (elCheckoutBenefitsContent && !elCheckoutBenefitsContent.classList.contains("hidden"))
      || (elCheckoutBenefitDetailContent && !elCheckoutBenefitDetailContent.classList.contains("hidden"))
    );
  }

  async function reopenCheckoutBenefitsHost({ sourceScreen, previewRequest = null, sectionFilter = null, returnContext = null } = {}) {
    const resolvedSourceScreen = normalizeCheckoutBenefitsSourceScreen(
      sourceScreen,
      getActiveCheckoutBenefitsSourceScreen("checkout")
    );
    const resolvedSectionFilter = normalizeCheckoutBenefitsSectionFilter(
      sectionFilter
      || openCartSheetCtx?.benefitsSectionFilter
      || sheetNavigationState?.data?.sectionFilter
      || null
    );
    const resolvedReturnContext = returnContext
      || openCartSheetCtx?.benefitsReturnContext
      || sheetNavigationState?.data?.returnContext
      || null;
    if (typeof openCartSheetCtx?.showSheetBenefits === "function" && hasLiveCartSheetContext()) {
      await openCartSheetCtx.showSheetBenefits(previewRequest, {
        sourceScreen: resolvedSourceScreen,
        sectionFilter: resolvedSectionFilter,
        returnContext: resolvedReturnContext,
      });
      return true;
    }
    if (typeof showDesktopBenefitsView === "function") {
      await showDesktopBenefitsView(previewRequest, {
        sourceScreen: resolvedSourceScreen,
        sectionFilter: resolvedSectionFilter,
        returnContext: resolvedReturnContext,
      });
      return true;
    }
    return false;
  }

  function renderCheckoutBenefitsAuthRequired(container, { sourceScreen } = {}) {
    if (!container) return;
    const box = document.createElement("div");
    box.className = "shop-favorites-auth";

    const note = document.createElement("div");
    note.className = "muted shop-favorites-empty";
    note.textContent = "Войдите в профиль, чтобы увидеть выгоды.";
    box.appendChild(note);

    const authBtn = document.createElement("button");
    authBtn.type = "button";
    authBtn.className = "btn";
    authBtn.textContent = "Войти";
    authBtn.addEventListener("click", () => {
      if (isDesktopBenefitsHostActive() && typeof openProfilePanel === "function") {
        void openProfilePanel(null, {
          forceOpen: true,
          onLoginSuccess: () => {
            void reopenCheckoutBenefitsHost({
              sourceScreen: normalizeCheckoutBenefitsSourceScreen(
                sourceScreen,
                getActiveCheckoutBenefitsSourceScreen("checkout")
              ),
            });
          },
        });
        return;
      }
      if (typeof openProfileSheet === "function") {
        openProfileSheet({
          onLoginSuccess: () => {
            void reopenCheckoutBenefitsHost({
              sourceScreen: normalizeCheckoutBenefitsSourceScreen(
                sourceScreen,
                getActiveCheckoutBenefitsSourceScreen("checkout")
              ),
            });
          },
        });
      }
    });
    box.appendChild(authBtn);
    container.appendChild(box);
  }

