      badge.setAttribute("aria-label", "\u041c\u043e\u0436\u043d\u043e \u0441\u043e\u0432\u043c\u0435\u0449\u0430\u0442\u044c");
      badge.innerHTML = '<i class="fas fa-link" aria-hidden="true"></i>';
      meta.appendChild(badge);
