    if (openCartSheetCtx) {
      openCartSheetCtx.addressFormReturnScreen = null;
    }

    clearSheetAddressTitleMode();
    if (window.AppModal?.setTitle) window.AppModal.setTitle("Точка самовывоза");
    setSheetHeaderMode("cart");
